package csu.mengya.controller;
import csu.mengya.db.AppDatabase;import javafx.beans.property.*;import javafx.collections.*;import javafx.fxml.*;import javafx.scene.control.*;import java.net.URL;import java.util.ResourceBundle;
public class TodoController implements Initializable { @FXML TextField titleField;@FXML ComboBox<String> priorityBox;@FXML Spinner<Integer> tomatoSpinner;@FXML TableView<Todo> todoTable;@FXML TableColumn<Todo,String> doneColumn,titleColumn,priorityColumn,statusColumn;@FXML TableColumn<Todo,Number> tomatoColumn;@FXML Label todoStatus;final ObservableList<Todo> items=FXCollections.observableArrayList();public void initialize(URL u,ResourceBundle r){priorityBox.setItems(FXCollections.observableArrayList("高","中","低"));priorityBox.setValue("中");tomatoSpinner.setValueFactory(new SpinnerValueFactory.IntegerSpinnerValueFactory(1,20,1));titleColumn.setCellValueFactory(x->x.getValue().title);priorityColumn.setCellValueFactory(x->x.getValue().priority);tomatoColumn.setCellValueFactory(x->x.getValue().tomatoes);doneColumn.setCellValueFactory(x->x.getValue().done.asString());statusColumn.setCellValueFactory(x->new SimpleStringProperty(x.getValue().done.get()?"已完成":"待完成"));todoTable.setItems(items);load();todoTable.getSelectionModel().selectedItemProperty().addListener((o,a,b)->{if(b!=null){titleField.setText(b.title.get());priorityBox.setValue(b.priority.get());tomatoSpinner.getValueFactory().setValue(b.tomatoes.get());}});}void load(){items.clear();for(AppDatabase.TodoRow r:AppDatabase.todos())items.add(new Todo(r.id(),r.title(),r.priority(),r.tomatoes(),r.done()));}@FXML void addTodo(){String t=titleField.getText().trim();if(t.isEmpty()){todoStatus.setText("请输入任务名称");return;}AppDatabase.addTodo(t,priorityBox.getValue(),tomatoSpinner.getValue());load();titleField.clear();todoStatus.setText("任务已添加");}@FXML void completeSelected(){Todo t=todoTable.getSelectionModel().getSelectedItem();if(t!=null){AppDatabase.updateTodo(t.id,t.title.get(),t.priority.get(),t.tomatoes.get(),true);load();todoStatus.setText("任务已完成");}}@FXML void deleteSelected(){Todo t=todoTable.getSelectionModel().getSelectedItem();if(t!=null){AppDatabase.deleteTodo(t.id);load();todoStatus.setText("任务已删除");}}@FXML void updateSelected(){Todo t=todoTable.getSelectionModel().getSelectedItem();if(t!=null){AppDatabase.updateTodo(t.id,titleField.getText().trim(),priorityBox.getValue(),tomatoSpinner.getValue(),t.done.get());load();todoStatus.setText("任务已更新");}}static class Todo{final long id;final StringProperty title=new SimpleStringProperty(),priority=new SimpleStringProperty();final IntegerProperty tomatoes=new SimpleIntegerProperty();final BooleanProperty done=new SimpleBooleanProperty();Todo(long i,String t,String p,int n,boolean d){id=i;title.set(t);priority.set(p);tomatoes.set(n);done.set(d);}}}